def occurrences(start, freq, interval, count, until, byweekday, exdates):
    from datetime import datetime, timedelta

    start_date = datetime.strptime(start, '%Y-%m-%d').date()
    until_date = datetime.strptime(until, '%Y-%m-%d').date() if until else None
    exdates_set = set(exdates) if exdates else set()

    candidates = []

    if freq == 'daily':
        k = 0
        while True:
            candidate = start_date + timedelta(days=k * interval)
            if until_date and candidate > until_date:
                break
            if count and len(candidates) >= count:
                break
            candidates.append(candidate)
            k += 1

    elif freq == 'weekly':
        start_weekday = start_date.weekday()
        if byweekday is None:
            target_weekdays = [start_weekday]
        else:
            target_weekdays = list(set(byweekday))

        start_week_number = start_date.isocalendar()[1]
        start_year = start_date.year

        k = 0
        while True:
            if count and len(candidates) >= count:
                break

            # Calculate the Monday of week k*interval starting from start's week
            weeks_offset = k * interval
            target_date = start_date + timedelta(weeks=weeks_offset)
            monday_of_target_week = target_date - timedelta(days=target_date.weekday())

            # Generate candidates for each target weekday in this week
            for weekday in target_weekdays:
                candidate = monday_of_target_week + timedelta(days=weekday)
                if candidate < start_date:
                    continue
                if until_date and candidate > until_date:
                    break
                candidates.append(candidate)

            if until_date and (monday_of_target_week + timedelta(days=6) > until_date):
                break

            k += 1

    elif freq == 'monthly':
        target_day = start_date.day
        year = start_date.year
        month = start_date.month

        k = 0
        while True:
            if count and len(candidates) >= count:
                break

            # Calculate target month
            total_months = (year - start_date.year) * 12 + (month - start_date.month)
            if total_months % interval == 0 and total_months >= 0:
                # Try to create a date with target_day in this month
                try:
                    candidate = datetime(year, month, target_day).date()
                    if candidate >= start_date:
                        if until_date and candidate > until_date:
                            break
                        candidates.append(candidate)
                except ValueError:
                    # Day doesn't exist in this month, skip
                    pass

            # Move to next month
            month += 1
            if month > 12:
                month = 1
                year += 1

            if until_date and datetime(year, month, 1).date() > until_date:
                break

            k += 1

    # Remove duplicates and sort
    candidates = sorted(set(candidates))

    # Apply count limit if needed
    if count:
        candidates = candidates[:count]

    # Apply until limit if needed
    if until_date:
        candidates = [c for c in candidates if c <= until_date]

    # Remove exdates
    candidates = [c for c in candidates if c.strftime('%Y-%m-%d') not in exdates_set]

    return [c.strftime('%Y-%m-%d') for c in candidates]

